-- seed: Pallav's four roles (viewer, editor, admin, super_admin) and the two portal roles (guest, corporate), with each role's grants on MJ's four levels
-- GENERATED by db/scripts/generate-platform-seeds.ts. Level rule: the highest of view < create < edit < delete(full) a role holds;
-- export (PDF) is folded into the level. Each row below is the role's FULL effective grant (the ladder is already included).
-- Built-in roles belong to no hotel (hotel_id NULL).

INSERT INTO platform.roles (key, name, description, icon, accent, level, inherits, is_system)
SELECT v.key, v.name, v.description, v.icon, v.accent, v.level, v.inherits, true
FROM (VALUES
  ('viewer', 'Viewer', 'Reads every screen and report, and changes nothing.', 'bi-eye', '#64748B', 1, true),
  ('editor', 'Editor', 'Records the day''s work and corrects it. Cannot delete or manage accounts.', 'bi-pencil-square', '#0F766E', 2, true),
  ('admin', 'Admin', 'Runs the day to day. Deletes records, manages Editors and Viewers.', 'bi-person-gear', '#B45309', 3, true),
  ('super_admin', 'SuperAdmin', 'Owns the system. The only role that can change roles, Master Data and force mode.', 'bi-shield-fill-check', '#6D28D9', 4, true),
  ('guest', 'Guest', 'A hotel guest using the guest portal. Sees only their own bookings, bills and advances.', 'bi-person', '#64748B', 1, false),
  ('corporate', 'Corporate', 'A company''s contact using the corporate portal. Sees only their own company''s bookings, bills and ledger.', 'bi-buildings', '#64748B', 1, false)
) AS v (key, name, description, icon, accent, level, inherits)
ON CONFLICT (key) WHERE hotel_id IS NULL DO NOTHING;

