  ('editor', 'payroll', 'edit'),
  ('editor', 'reports', 'view'),
  ('admin', 'dashboard', 'view'),
  ('admin', 'revenue', 'full'),
  ('admin', 'expense', 'full'),
  ('admin', 'handover', 'full'),
  ('admin', 'bills', 'full'),
  ('admin', 'companies', 'full'),
  ('admin', 'payroll', 'full'),
  ('admin', 'reports', 'view'),
  ('admin', 'users', 'full'),
  ('admin', 'access', 'view'),
  ('admin', 'users.password', 'full'),
  ('admin', 'users.activity', 'full'),
  ('admin', 'system.backdate', 'full'),
  ('super_admin', 'dashboard', 'view'),
  ('super_admin', 'revenue', 'full'),
  ('super_admin', 'expense', 'full'),
  ('super_admin', 'handover', 'full'),
  ('super_admin', 'bills', 'full'),
  ('super_admin', 'companies', 'full'),
  ('super_admin', 'payroll', 'full'),
  ('super_admin', 'reports', 'view'),
  ('super_admin', 'pms', 'view'),
  ('super_admin', 'pms.board', 'full'),
  ('super_admin', 'pms.reservations', 'full'),
  ('super_admin', 'pms.stays', 'full'),
  ('super_admin', 'pms.rooms', 'full'),
  ('super_admin', 'website', 'view'),
  ('super_admin', 'website.enquiries', 'full'),
  ('super_admin', 'website.rooms', 'full'),
  ('super_admin', 'website.rates', 'full'),
  ('super_admin', 'website.calendar', 'full'),
  ('super_admin', 'website.gallery', 'full'),
